test(\"capacity counts unique tenant visits, preserves IDs and permits same-crew no-ops\", async () => {
  const f = await fixture();
  const result = await importRoutes(f.file, \"a\", \"u\", [row(\"007\"), row(\"007\"), row(\"7\")], true);
