  const before = await f.bytes();
  expect((await importRoutes(f.file, \"a\", \"overflow\", [row(\"8\")], true)).status).toBe(\"rejected\");
  expect(await f.bytes()).toBe(before);
  expect((await importRoutes(f.file, \"b\", \"u\", [row(\"007\")], true)).status).toBe(\"applied\");
});

test(\"unavailable crews and conflicting assignments reject atomically\", async () => {
  const f = await fixture();
  const before = await f.bytes();
  for (const rows of [[row(\"1\", \"paused\")], [row(\"1\", \"archived\")], [row(\"1\"), row(\"1\", \"other\")], [row(\"1\"), row(\"2\"), row(\"3\")]]) {
