  const before = await f.bytes();
  for (const apply of [false, true]) {
    expect(await importRoutes(f.file, \"a\", \"u\", rows, apply)).toEqual({ ...applied, status: \"replay\" });
    expect(await f.bytes()).toBe(before);
    for (const changed of [[row(\"2\"), row(\"1\")], [row(\"1\")], [row(\"1\"), row(\"2\", \"other\")]]) {
      expect((await importRoutes(f.file, \"a\", \"u\", changed, apply)).status).toBe(\"rejected\");
