test(\"upload replay is persistent, tenant scoped and compares ordered public row values\", async () => {
  await fixture(async file => {
    const rows = [{ visitId: \"0007\", crewId: \"001\" }, { visitId: \"visit-A\", crewId: \"001\" }];
    const first = await importRoutes(file, \"a\", \"__proto__\", rows, true);
    expect(first.status).toBe(\"applied\");
    const committed = await readFile(file, \"utf8\");
    for (const apply of [false, true]) {
      const replay = await importRoutes(file, \"a\", \"__proto__\", rows.map(r => ({ crewId: r.crewId, visitId: r.visitId })), apply);
      expect(replay).toEqual({ ...first, status: \"replay\" });
      expect(await readFile(file, \"utf8\")).toBe(committed);
      for (const changed of [[...rows].reverse(), [rows[0]"'!], [...rows, rows[0]!], [{visitId:"changed",crewId:"001"}]]) {
        const result = await importRoutes(file, "a", "__proto__", changed, apply);
        expect(result.status).toBe("rejected");
        expect(result.errors.length).toBeGreaterThan(0);
        expect(await readFile(file, "utf8")).toBe(committed);
      }
    }
    const otherTenant = await importRoutes(file, "b", "__proto__", rows, true);
    expect(otherTenant.status).toBe("applied");
    expect(otherTenant.assignments).toEqual([
      { tenant: "b", visitId: "0007", crewId: "001" },
      { tenant: "b", visitId: "visit-A", crewId: "001" },
    ]);
    // Persisted receipt works even after crew eligibility changes; replay has no new effects.
    const state = JSON.parse(await readFile(file, "utf8")) as State;
    state.crews[0]!.status = "archived";
    await writeFile(file, JSON.stringify(state));
    expect((await importRoutes(file, "a", "__proto__", rows, true)).status).toBe("replay");
    expect((await importRoutes(file, "a", "fresh", rows, true)).assignments).toEqual([]);
    expect((await importRoutes(file, "a", "fresh", rows, true)).status).toBe("replay");
  }, { crews: [crew(), crew("001", 2, "b")] });
});

