  await expect(client.sync()).rejects.toThrow('pull failed');
  expect(client.pending()).toEqual([]);
  fail = false;
  await f.client('team', 'phone', transport).sync();
  expect(cursors).toEqual([0, 1, 1]);
  expect((await remote.pull(0)).cursor).toBe(2);
});

